using System;using System.Collections.Generic;using System.Web.Security;using System.Web.UI;using ForteMove.Business.Services;using ForteMove.Models.Common;using ForteMove.Models.Security;using ForteMove.Web.Infrastructure;
namespace ForteMove.Web.Account{public partial class ChangePassword:Page{protected override void OnInit(EventArgs e){ForteMovePrincipal p=Context.User as ForteMovePrincipal;if(p==null||!p.Identity.IsAuthenticated){Response.Redirect(ResolveUrl(FormsAuthentication.LoginUrl),true);return;}ViewStateUserKey=p.Context.UserAccountId.ToString();base.OnInit(e);}protected void Page_Load(object sender,EventArgs e){ForteMovePrincipal p=Context.User as ForteMovePrincipal;if(!IsPostBack&&p!=null&&!p.Context.MustChangePassword)RedirectHome(p.Context.Role);}protected void btnChangePassword_Click(object sender,EventArgs e){ForteMovePrincipal p=Context.User as ForteMovePrincipal;ServiceResult<bool> result=ServiceFactory.CreateAuthenticationService().ChangePassword(new ChangePasswordRequest{UserAccountId=p.Context.UserAccountId,CurrentPassword=txtCurrentPassword.Text,NewPassword=txtNewPassword.Text,ConfirmPassword=txtConfirmPassword.Text,ClientIpAddress=ClientIpAddress.From(Request)});if(!result.Succeeded){Show(result.Errors);return;}RedirectHome(p.Context.Role);}protected void btnSignOut_Click(object sender,EventArgs e){FormsAuthentication.SignOut();Session.Clear();Session.Abandon();Response.Redirect(ResolveUrl("~/Account/Login.aspx"),true);}private void Show(IEnumerable<ValidationError> errors){pnlErrors.Visible=true;rptErrors.DataSource=errors;rptErrors.DataBind();}private void RedirectHome(RoleCode role){if(role==RoleCode.Driver)Response.Redirect(ResolveUrl("~/Driver/Account.aspx"),true);if(role==RoleCode.TransportAdministrator)Response.Redirect(ResolveUrl("~/Admin/Dashboard.aspx"),true);Response.Redirect(ResolveUrl("~/Errors/AccessDenied.aspx"),true);}}}
